import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {createHash} from 'node:crypto';
const root=new URL('../variants/',import.meta.url);
const baseline=await import(new URL('baseline/lib/index.js',root));
const combined=await import(new URL('inplace/lib/index.js',root));
let state=123456789;const random=()=>{state^=state<<13;state^=state>>>17;state^=state<<5;return(state>>>0)/4294967296;};
const parts=['','a','b.png','%2e','%2E%2e','.','..','%2F','%3a','%ZZ','a:b','x&y','日本語','a\\b','..x'];
let paths=0;
for(let i=0;i<20000;i++){
 const url='https://example.test/'+Array.from({length:1+Math.floor(random()*7)},()=>parts[Math.floor(random()*parts.length)]).join('/')+(random()<.5?'/':'')+'?a=b&b=c';
 for(const html of [false,true])for(const search of [false,true]){
  const create=api=>{try {const r=api.resource.createResource({type:html?2:1,depth:0,url,refUrl:url,keepSearch:search,localRoot:'/out'});return Object.fromEntries(['url','savePath','refSavePath','replacePath','downloadLink'].map(k=>[k,r[k]]));}catch(error){return {error:error.name,message:error.message};}};
  assert.deepEqual(create(combined),create(baseline),JSON.stringify({url,html,search}));paths++;
 }
}
const fixtures=['<style>.x{color:red}</style>','<style>.x{content:"<b>&amp;"}</style>',
 '<style>.x{background:url(a.png)}</style>','<style>.x{background:url(data:a,b)}</style>',
 '<style>/*url(a)*/ .x {color:red}</style>','<style></style>',
 await readFile(new URL('../fixtures/mdn.html',import.meta.url),'utf8')];
async function process(api,body,mutate){
 const options=api.options.defaultDownloadOptions({...api.lifeCycle.defaultLifeCycle(),processBeforeDownload:[(resource,_element,parent)=>{
  if(mutate)parent.meta.doc?.('style').text('hook mutation');
  resource.replacePath=resource.rawUrl;return resource;
 }]});
 const pipeline=new api.downloader.PipelineExecutorImpl(options,options.req,options);
 const parent={...api.resource.createResource({type:2,depth:0,url:'https://example.test/index.html',refUrl:'https://example.test/',localRoot:'/out'}),body};
 const resources=[];await pipeline.processAfterDownload(parent,value=>resources.push(...Array.isArray(value)?value:[value]));
 return {html:parent.meta.doc.html(),resources:resources.map(x=>[x.url,x.replacePath])};
}
for(const html of fixtures)for(const mutate of [false,true])assert.deepEqual(await process(combined,html,mutate),await process(baseline,html,mutate));
console.log(JSON.stringify({passed:true,pathComparisons:paths,htmlComparisons:fixtures.length*2}));

