import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import {makeRunner} from './interleaved-cases.mjs';
const root=new URL('../',import.meta.url).pathname;
const pressure=process.argv[2]==='pressure';const kind=pressure?'interleaved-pressure':'interleaved-focused';
const cases=['css-unique','css-duplicates','svg-links','html-links','link-chain'];
const rounds=18;const output=root+'runs/'+kind+'-'+new Date().toISOString().replaceAll(':','-');await fs.mkdir(output,{recursive:true});
const protocol={kind,rounds,cases,node:process.version,pressure,minimumQualifyingRounds:12,calibrationGroups:3,bootstrapSamples:10000,seed:123456789,control:'95% interval includes zero and lies within +/-5%',unit:'Two-observation per-variant median, paired by interleaved round; all variants in one warmed process',noise:'1.5 times median of three calibration group maxima, fixed before measurement; entire case triplet excluded on any CPU/IO exceedance'};
const median=v=>{const a=[...v].sort((a,b)=>a-b);return(a[(a.length-1)>>1]+a[a.length>>1])/2;};
function interval(v){let state=123456789;const rand=()=>{state^=state<<13;state^=state>>>17;state^=state<<5;return(state>>>0)/4294967296;};const a=Array.from({length:10000},()=>median(v.map(()=>v[Math.floor(rand()*v.length)]))).sort((a,b)=>a-b);const q=p=>{const x=p*(a.length-1),lo=Math.floor(x);return a[lo]+(a[Math.ceil(x)]-a[lo])*(x-lo);};return{median:median(v),interval95:[q(.025),q(.975)]};}

const runners=await Promise.all(['baseline','final','final'].map(name=>makeRunner(root+'variants/'+name+'/lib/index.js',pressure)));
const startedAt=new Date().toISOString();const samples=[],calibration=[];
function maxima(rows){assert.equal(rows.length,6);return Object.fromEntries(['cpuMs','ioMs'].map(m=>[m,Math.max(...rows.flatMap(r=>[r.noiseBefore[m],r.noiseAfter[m]]))]));}
try{
 for(const key of cases)for(const runner of runners)await runner.warm(key);
 for(let round=0;round<3;round++)for(const key of cases)for(let k=0;k<3;k++)for(let sample=0;sample<2;sample++){const variant=(round+k)%3;calibration.push({...await runners[variant].sample(key),variant,round,sample});}
 const thresholds=Object.fromEntries(cases.map(key=>[key,Object.fromEntries(['cpuMs','ioMs'].map(m=>[m,1.5*median(Array.from({length:3},(_,round)=>maxima(calibration.filter(x=>x.case===key&&x.round===round))[m]))]))]));
 await fs.writeFile(output+'/calibration.json',JSON.stringify({protocol,calibration,thresholds},null,2));
 for(let round=0;round<rounds;round++){
  const order=[0,1,2];order.push(...order.splice(0,round%3));if(round%2)order.reverse();
  for(const key of cases)for(const variant of order)for(let sample=0;sample<2;sample++)samples.push({...await runners[variant].sample(key),variant,round,sample});
  console.log(JSON.stringify({kind,round:round+1,rounds}));
 }
const comparisons=[];
for(const key of cases){const rows=samples.filter(x=>x.case===key);assert.equal(new Set([...rows,...calibration.filter(x=>x.case===key)].map(x=>x.sha256)).size,1);const excluded=[];const included=[];for(let round=0;round<rounds;round++){const mx=maxima(rows.filter(x=>x.round===round));const metrics=Object.keys(mx).filter(m=>mx[m]>thresholds[key][m]);if(metrics.length)excluded.push({round,metrics});else included.push(round);}
 const comparison={case:key,acceptedRounds:included.length,excluded,status:'insufficient-rounds'};
 if(included.length>=protocol.minimumQualifyingRounds){const grouped=metric=>included.map(round=>[0,1,2].map(variant=>median(rows.filter(x=>x.round===round&&x.variant===variant).map(x=>x[metric]))));const timing=grouped('totalMs');const control=interval(timing.map(x=>100*(x[2]/x[1]-1)));const effect=interval(timing.map(x=>100*(x[1]/x[0]-1)));const effectControl=interval(timing.map(x=>100*(x[2]/x[0]-1)));const[lo,hi]=control.interval95;const stable=lo<=0&&hi>=0&&lo>=-5&&hi<=5;
 Object.assign(comparison,{status:!stable?'unresolved-control':effect.interval95[1]<0&&effectControl.interval95[1]<0?'faster':effect.interval95[0]>0&&effectControl.interval95[0]>0?'slower':'unresolved-difference',control,effect,effectControl,medianMs:[0,1,2].map(v=>median(timing.map(x=>x[v]))),memory:{}});
 for(const metric of ['heapPeakObserved','retainedHeapDelta','rss','external','arrayBuffers','gcCount','gcMs','maxRssKiB'].filter(metric=>typeof rows[0][metric]==='number')){const v=grouped(metric);comparison.memory[metric]={medians:[0,1,2].map(i=>median(v.map(x=>x[i]))),pairedDelta:interval(v.map(x=>x[1]-x[0]))};}
 }
 comparisons.push(comparison);
}

 const result={protocol,startedAt,finishedAt:new Date().toISOString(),calibration,thresholds,samples,comparisons};await fs.writeFile(output+'/results.json',JSON.stringify(result,null,2));await fs.writeFile(root+'latest-'+kind+'.json',JSON.stringify({output}));console.log(JSON.stringify({output,comparisons:comparisons.map(({case:key,status,acceptedRounds,effect,control})=>({case:key,status,acceptedRounds,effect,control}))}));
}finally{for(const runner of runners)await runner.close();}

